use std::{fs,path::{Path,PathBuf},collections::BTreeMap,fmt::Write,process::Command};use serde_json::{json,Value};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-g2-level-tree";const REPORT:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-g2-level-tree";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn walk(p:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){walk(&e.path(),out)}else if e.file_type().unwrap().is_file(){out.push(e.path());}}}
fn state(phase:&str,experiment:Value){let mut s=read("/tmp/zopro-latest-optimization-status.json");s["current_work"]=json!({"root":R,"phase":phase,"production_accepted_unchanged":true,"new_cloud_resources":false});s["status"]=json!(phase);if experiment.is_object(){s["experiment"]=experiment.clone();}if let Some(c)=experiment.get("commit"){s["latest_pushed_commit"]=c.clone();}save("/tmp/zopro-latest-optimization-status.json",&s);let p="/home/ubuntu/src/zopro-cpu-perf-handoff.md";let old=fs::read_to_string(p).unwrap();fs::write(p,format!("# CURRENT — G2 LEVEL TREE: {phase}\n\nRoot{R},productionunchanged,noAWS. Component-only actual1x2/2x2Bweights;w1/16/32sevenblocks7timed+2primes84processesTHENtwo199Hzgatedprofiles64+2plus86referencecalls=974rawqueries,noSDK/Gnark/prior5958unchanged.112core/raw2/cubic6expected. Allhelpersbeforetiming. Goalall8CPU10xACTIVEUNMET.\n\n{old}")).unwrap();}
fn close(){let r=Path::new(R);let a=read(r.join("analysis.json"));assert_eq!(a["raw_query_calls"],974);let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");for(rel,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(rel)),h.as_str().unwrap());}let mut text=String::from("# Grouped-level G2 reduction trees\n\n");writeln!(text,"The component {} its frozen speed gate. Production dispatch and accepted170source files remain unchanged. This is an isolated rawG2 caller study, not full-proof or M5 speed evidence.\n",if a["component_gate_passed"]==true{"passes"}else{"does not pass"}).unwrap();text.push_str("Ordinary12-bit component buckets are counted/scattered through signedu32 indices. Existing complete affine kernels batch pairs across256buckets at each tree level, instead of retaining one growing accumulator per bucket. G2phi2 split,two partitions,high-bucket phi,narrow top digit,part merging and weighted final reduction remain unchanged. No new pool,key table,field formula or SDK route. The tree introduces input-order changes,temporary point copies and a separate low/high merge. It differs from old tiny per-bucket trees and linear routed bucket rounds.\n\nTyped conservative admission sums all possible suspended routing/group buffers above the original raw-query forecast. Explicit denial errors prevent a benchmark silently using another implementation. This is not a universal retained memory allocation or a process-RAM guarantee. No pressure/phone/TEE/large-circuit/concurrency qualification is claimed.\n\n## Fixed caller comparison\n\nActual1x2/2x2B2 points and solved fixture scalars. Compressed key and current Euler point order agree exactly. Seven rotated/reversed fresh-process blocks,seven timed calls after two primes; each process also computes one stream reference. CPU0,w16CPUs0–15,w32CPUs0–31. Timing includes scalar clone,decomposition,admission,routing,allocations,fill/reduction,result normalization/equality check and temporary drops. It excludes key loading,witness solving,reference setup,scalar grouping,other queries,blinding,SDK verification and serialization. Both modes pay allocator accounting atomics; this can affect an allocation-heavy candidate and is not plain SDK timing.\n\n|Case|Stream ms|Tree ms|Paired tree/stream|Wins/7|Stream/tree requested peak MiB above inputs|Stream/tree whole-process RSS MiB|\n|---|---:|---:|---:|---:|---:|---:|\n");for shape in ["1x2","2x2"]{for workers in [1,16,32]{let name=format!("{shape}-w{workers}");let c=&a["comparisons"][&name];let s=&c["modes"]["stream"];let t=&c["modes"]["tree"];writeln!(text,"|{name}|{:.6}|{:.6}|{:.6}|{}|{:.3}/{:.3}|{:.2}/{:.2}|",s["request_ms"].as_f64().unwrap(),t["request_ms"].as_f64().unwrap(),c["paired_geomean"].as_f64().unwrap(),c["wins"],s["max_requested_above_inputs_bytes"].as_f64().unwrap()/1048576.,t["max_requested_above_inputs_bytes"].as_f64().unwrap()/1048576.,s["max_process_RSS_mib"].as_f64().unwrap(),t["max_process_RSS_mib"].as_f64().unwrap()).unwrap();}}
 text.push_str("\nGate: positive primary paired geometric ratio against stream at both16/32workers,at least4/7wins each,and2x2ratios<=1.02atboth. Workers1isdescriptive. No minimum positive gain floor or changed gate. Failures:\n\n");if a["failures"].as_array().unwrap().is_empty(){text.push_str("- None.\n")}else{for f in a["failures"].as_array().unwrap(){writeln!(text,"- {}",f.as_str().unwrap()).unwrap();}}
 text.push_str("\nRequested peaks count caller layout bytes above prepared inputs,including the scalar clone and returned buffers,forwarding to the accepted allocator. They are not minimum RAM or an admission guarantee. Whole-process RSS includes loader/reference/primes. Every timed sample checks its peak against the typed forecast plus the input-scalar clone; all bounds pass. Full112nativecore,raw2/cubic6andgeneratorcheckpass;new3coretestscovergeneratororacles across workers,actual-size randomG2andcheckedforecasts. Field math is unchanged and its prior qualification is inherited.\n\nAll84latencies precede two primary32profiles,199Hz,64timedcalls after two primes. The existing FIFOs enable profiling after input/reference preparation. Profiles are user-cycle samples and not latency observations.\n\n|Mode|Samples|Lost records|\n|---|---:|---:|\n");for mode in ["stream","tree"]{writeln!(text,"|{mode}|{}|{}|",a["profiles"][mode]["samples"],a["profiles"][mode]["lost_records"]).unwrap();}
 text.push_str("\nAcross latency/profile processes:974raw-query executions,including86reference setups. There are no SDK proofs or Gnark exports;prior5958stays unchanged. This component cannot establish the original all-eightCPU10× goal. [Latest all-nine rejected-candidate comparison](../2026-10-26-prefix-pool/README.md) retains supplied CPU/Metal references; no whole-proof gain is inferred by dividing them by a component time. No new AWS or Aeglos measurement.\n\nAll helpers compiled before latency. No successful capture is repeated or excluded. Candidate source,protocol,rows,requested/RSS data and decoded profiles are retained in [analysis](artifacts/analysis.json),[design](artifacts/design.md),[source audit](artifacts/source-audit.json),[jobs](artifacts/jobs.json),[artifact index](artifacts/artifact-index.json). Rawperf,binaries and large inputs stay local with hashes.\n");let dest=Path::new(REPORT).join("artifacts");fs::create_dir_all(&dest).unwrap();fs::write(Path::new(REPORT).join("README.md"),text).unwrap();let mut files=Vec::new();for folder in ["candidate","native","measure","support"]{walk(&r.join(folder),&mut files);}for e in fs::read_dir(r).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_file(){files.push(e.path());}}let mut index=BTreeMap::new();for p in files{let ext=p.extension().and_then(|x|x.to_str()).unwrap_or("");if !matches!(ext,"rs"|"json"|"md"|"log"|"txt"|"toml"|"lock"|"bin"){continue;}let target=dest.join(p.strip_prefix(r).unwrap());fs::create_dir_all(target.parent().unwrap()).unwrap();fs::copy(&p,&target).unwrap();index.insert(p.strip_prefix(r).unwrap().display().to_string(),hash(&target));}for(p,h)in &index{assert_eq!(hash(dest.join(p)),*h);}save(dest.join("artifact-index.json"),&json!({"sha256":index,"raw_profiles_local_only":a["profiles"]}));let c=json!({"status":"complete grouped-level G2 component","root":R,"report":format!("{REPORT}/README.md"),"component_gate_passed":a["component_gate_passed"],"raw_query_calls":974,"new_SDK_proofs":0,"new_Gnark_exports":0,"prior_proof_count":5958,"adopted":false,"goal_achieved":false,"profiles":a["profiles"],"artifact_hashes":index.len()});save(r.join("closeout.json"),&c);state("G2 level-tree component closed; ready to commit/push",c);}
fn pushed(){let o=Command::new("git").args(["rev-parse","HEAD"]).output().unwrap();assert!(o.status.success());let commit=String::from_utf8(o.stdout).unwrap().trim().to_owned();let o=Command::new("git").args(["-c","url.https://github.com/.insteadOf=git@github.com:","-c","credential.helper=!gh auth git-credential","ls-remote","origin","refs/heads/sergei/zopro-cpu-perf"]).output().unwrap();assert!(o.status.success());assert_eq!(String::from_utf8(o.stdout).unwrap().split_whitespace().next().unwrap(),commit);let mut c=read(Path::new(R).join("closeout.json"));c["commit"]=json!(commit);c["remote_verified"]=json!(true);state("G2 level-tree component closed/pushed; no adoption",c);}
fn main(){match std::env::args().nth(1).as_deref(){Some("close")=>close(),Some("pushed")=>pushed(),Some(p)=>state(p,Value::Null),_=>panic!("mode")}}
